create table if not exists public.ils_professional_assignment_mutation_audit (id uuid primary key default gen_random_uuid(),assignment_link_id uuid,work_item_id uuid,work_stream text,professional_user_id uuid,operation text not null,from_status text,to_status text,decision text not null,reason_code text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_audit enable row level security; revoke all on public.ils_professional_assignment_mutation_audit from anon,authenticated; create or replace function public.ils_professional_assignment_mutation_gate(p_assignment_link_id uuid,p_operation text,p_to_status text default null) returns boolean language plpgsql security definer stable set search_path=public as $$ declare v record; begin if auth.uid() is null or p_assignment_link_id is null or p_operation not in ('ACTIVATE','PAUSE','REVOKE','COMPLETE') then return false; end if; select l.id,l.work_item_id,l.work_stream,l.professional_user_id,l.link_status into v from public.ils_professional_work_assignment_links l where l.id=p_assignment_link_id and l.professional_user_id=auth.uid(); if not found then return false; end if; if p_operation='ACTIVATE' and p_to_status is distinct from 'ACTIVE' then return false; end if; if p_operation='PAUSE' and p_to_status is distinct from 'PAUSED' then return false; end if; if p_operation='REVOKE' and p_to_status is distinct from 'REVOKED' then return false; end if; if p_operation='COMPLETE' and p_to_status is distinct from 'COMPLETED' then return false; end if; if not public.ils_professional_assignment_transition_allowed(v.link_status,p_to_status) then return false; end if; if p_operation='ACTIVATE' and not public.ils_professional_assignment_is_current(v.work_item_id,v.work_stream,v.professional_user_id) then return false; end if; return true; end $$; revoke all on function public.ils_professional_assignment_mutation_gate(uuid,text,text) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_mutation_gate(uuid,text,text) to authenticated; create index if not exists idx_ils_assignment_mutation_audit_link on public.ils_professional_assignment_mutation_audit(assignment_link_id,created_at desc); create index if not exists idx_ils_assignment_mutation_audit_user on public.ils_professional_assignment_mutation_audit(professional_user_id,created_at desc);